konsole_tabs:
/* Generated by ~/.config/plasma-rice/rice.py from the wallpaper palette. Do not edit. */
QTabBar { background: rgba(17,15,14, 217); }
QTabBar::tab {
    background: transparent; color: #7f7977;
    border: 1px solid transparent; border-radius: 10px;
    padding: 4px 12px; margin: 8px 2px 2px 2px;
    min-width: 7em; max-width: 22em;
}
QTabBar::tab:first { margin-left: 12px; }
QTabBar::tab:hover:!selected { background: rgba(228,224,223, 20); color: #b5b0ae; }
QTabBar::tab:selected {
    background: rgba(207,201,199, 41); color: #e4e0df;
    border-color: rgba(207,201,199, 82);
}

zen:
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py from the wallpaper palette. Do not edit. */
:root, :host(:is(.anonymous-content-host, notification-message)) {
  --zen-primary-color: #cfc9c7 !important;
  --zen-branding-dark: #110f0e !important;
  --zen-colors-primary: color-mix(in srgb, #cfc9c7 22%, #161312) !important;
  --zen-colors-secondary: color-mix(in srgb, #cfc9c7 32%, #161312) !important;
  --zen-colors-tertiary: #0b0808 !important;
  --zen-colors-hover-bg: color-mix(in srgb, #cfc9c7 14%, #1a1716) !important;
  --zen-colors-primary-foreground: #e4e0df !important;
  --zen-colors-border: rgba(65,60,58, 0.55) !important;
  --zen-colors-border-contrast: rgba(65,60,58, 0.3) !important;
  --zen-colors-input-bg: #1a1716 !important;
  --zen-input-border-color: #413c3a !important;
  --zen-dialog-background: #161312 !important;
  --zen-urlbar-background: #1a1716 !important;
  --zen-main-browser-background: linear-gradient(135deg, rgba(47,45,44, 0.72) 0%, rgba(11,8,8, 0.84) 52%, rgba(48,45,45, 0.68) 100%) !important;
  --zen-main-browser-background-toolbar: linear-gradient(135deg, rgba(47,45,44, 0.72) 0%, rgba(11,8,8, 0.84) 52%, rgba(48,45,45, 0.68) 100%) !important;
  --toolbox-textcolor: #e4e0df !important;
  --toolbar-field-color: #e4e0df !important;
  --arrowpanel-background: #1a1716 !important;
  --arrowpanel-color: #e4e0df !important;
  --arrowpanel-border-color: rgba(65,60,58, 0.6) !important;
  --panel-separator-color: rgba(65,60,58, 0.6) !important;
  --focus-outline-color: #cfc9c7 !important;
  --zen-sidebar-themed-icon-fill: #b5b0ae !important;
}

/* Zen paints the workspace gradient on these layers and sets its variables inline on them,
   so override the layers themselves (::before is the cross-fade target while switching spaces) */
.zen-browser-generic-background::after,
.zen-browser-generic-background::before {
  background: linear-gradient(135deg, rgba(47,45,44, 0.72) 0%, rgba(11,8,8, 0.84) 52%, rgba(48,45,45, 0.68) 100%) !important;
}

/* selected tab: a soft accent wash with a hairline, instead of plain white */
.tabbrowser-tab:is([selected], [multiselected]) .tab-background {
  background-color: rgba(207,201,199, 0.16) !important;
  box-shadow: inset 0 0 0 1px rgba(207,201,199, 0.32) !important;
}
.tabbrowser-tab:not([selected]):hover .tab-background {
  background-color: rgba(228,224,223, 0.07) !important;
}

/* command bar / url bar popup */
#urlbar[breakout-extend] > .urlbar-background,
#urlbar[breakout-extend] #urlbar-background {
  background-color: #1a1716 !important;
  border: 1px solid rgba(65,60,58, 0.7) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45) !important;
}
.urlbarView-row[selected] {
  background-color: rgba(207,201,199, 0.18) !important;
}

/* menus and popups */
menupopup, panel {
  --panel-background: #1a1716 !important;
  --panel-color: #e4e0df !important;
  --panel-border-color: rgba(65,60,58, 0.6) !important;
}
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py. Do not edit. */
:root {
  scrollbar-color: rgba(106,101,99, 0.7) transparent;
}
@-moz-document url("about:blank"), url("about:newtab"), url("about:home"), url("about:privatebrowsing") {
  html, body { background-color: #110f0e !important; }
}
